    stockNormal.repeat.set(2, 1);
    stockMat.normalMap = stockNormal;
    stockMat.normalScale.set(0.4, 0.4);
    const sp = new THREE.Shape();
    const SL = 0.11, hR = 0.0375, hB = 0.028;   // 半长、机匣端高、尾端高
    sp.moveTo(-SL, -hR);
    sp.lineTo(SL, -hB);
    sp.lineTo(SL, hB);
    sp.lineTo(-SL, hR);
    sp.closePath();
    const stockGeo = new THREE.ExtrudeGeometry(sp, {
      depth: 0.05, bevelEnabled: true, bevelThickness: 0.004, bevelSize: 0.004, bevelSegments: 2,
    });
    stockGeo.rotateY(-Math.PI / 2);   // shape X(长)→世界 Z，挤出→世界 X(宽)
    stockGeo.translate(X, -0.18, -0.22);
    const stock = new THREE.Mesh(stockGeo, stockMat);
    stock.castShadow = true;
    g.add(stock);

    // 两节式枪托接缝线（现实 AWP：上下两片尼龙枪托拼合线）
    const seam = new THREE.Mesh(new THREE.BoxGeometry(0.052, 0.003, 0.22), darkDarkMat || darkMat);
    seam.position.set(X, -0.205, -0.22);
    g.add(seam);

    // 贴腮垫（NEW，狙击枪特征）：枪托上方隆起，同木色
    const cheek = new THREE.Mesh(this._makeRoundedBox(0.042, 0.022, 0.1, 0.008), stockMat);
    cheek.position.set(X, -0.125, -0.26);
    g.add(cheek);

    // 枪托底板（橡胶，圆角）
    const stockPad = new THREE.Mesh(this._makeRoundedBox(0.052, 0.08, 0.01, 0.008), darkMat);
    stockPad.position.set(X, -0.18, -0.11);
    g.add(stockPad);

    // ---- 脚架（枪管下方两根细支柱，可展开）----
    const bipodLeg1 = new THREE.Mesh(new THREE.CylinderGeometry(0.004, 0.004, 0.12, 8), darkMat);
    bipodLeg1.position.set(X - 0.018, -0.22, -0.82);
    bipodLeg1.rotation.x = 0.15;
    g.add(bipodLeg1);
    const bipodLeg2 = bipodLeg1.clone();
    bipodLeg2.position.x = X + 0.018;
    g.add(bipodLeg2);

    // 枪口火光（对准 AWP 枪口末端，最远端）
    const flash = this._makeMuzzleFlashMesh(X, -0.16, -1.2);
    g.add(flash);
    g.userData.flash = flash;
    return g;
  }


